import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, Navigate } from 'react-router-dom';
import Home from './pages/Home';
import Dashboard from './pages/Dashboard';
import ManageParticipants from './pages/ManageParticipants';
import ManageJuries from './pages/ManageJuries';
import ManageQuestions from './pages/ManageQuestions';
import SimultaneousEvaluation from './pages/SimultaneousEvaluation';
import AdminHub from './pages/AdminHub';
import Navbar from './components/Navbar';
import Login from './pages/Login'; // Import the Login component
import './App.css';

// This component will wrap our protected routes
const ProtectedRoute = ({ children, authenticated }) => {
  return authenticated ? children : <Navigate to="/login" />;
};

const RequireJury = ({ children }) => {
  const role = sessionStorage.getItem('accessRole');
  return role === 'jury' ? children : <Home />;
};

const RequireAdmin = ({ children }) => {
  const role = sessionStorage.getItem('accessRole');
  return role === 'admin' ? children : <Home />;
};

function App() {
  // Check sessionStorage for authentication status
  const [authenticated, setAuthenticated] = useState(sessionStorage.getItem('isAuthenticated') === 'true');

  const handleSetAuthenticated = (isAuthenticated) => {
    sessionStorage.setItem('isAuthenticated', isAuthenticated);
    setAuthenticated(isAuthenticated);
  };

  return (
    <Router>
      {authenticated && <Navbar />}
      <div className="container">
        <Routes>
          <Route path="/login" element={<Login setAuthenticated={handleSetAuthenticated} />} />
          <Route 
            path="/" 
            element={
              authenticated ? <Navigate to="/home" /> : <Navigate to="/login" />
            } 
          />
          <Route path="/home" element={<ProtectedRoute authenticated={authenticated}><Home /></ProtectedRoute>} />
          <Route path="/manage-participants" element={<ProtectedRoute authenticated={authenticated}><RequireAdmin><ManageParticipants /></RequireAdmin></ProtectedRoute>} />
          <Route path="/manage-juries" element={<ProtectedRoute authenticated={authenticated}><RequireAdmin><ManageJuries /></RequireAdmin></ProtectedRoute>} />
          <Route path="/manage-questions" element={<ProtectedRoute authenticated={authenticated}><RequireAdmin><ManageQuestions /></RequireAdmin></ProtectedRoute>} />
          <Route path="/admin" element={<ProtectedRoute authenticated={authenticated}><RequireAdmin><AdminHub /></RequireAdmin></ProtectedRoute>} />
          <Route path="/evaluation-simultaneous" element={<ProtectedRoute authenticated={authenticated}><RequireJury><SimultaneousEvaluation /></RequireJury></ProtectedRoute>} />
          <Route path="/evaluation" element={<ProtectedRoute authenticated={authenticated}><RequireJury><SimultaneousEvaluation /></RequireJury></ProtectedRoute>} />
          <Route path="/dashboard" element={<ProtectedRoute authenticated={authenticated}><RequireAdmin><Dashboard /></RequireAdmin></ProtectedRoute>} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
